import{diff as create3dWidgetDiff}from"../../../../../../../../../🧊️generation3d/🏅️standards/🔖️1/🪆️subsets/✳️any/🧬️schema/🧬️mutations/🌱️create-widget/🔺️diff/🟦️.ts";

test("Generation declared camera schema admits independently specified complete IEEE words",()=>{const ajv=new Ajv({strict:false}),validate=ajv.compile({$defs:artifactSchema.$defs,$ref:"#/$defs/CameraJson"});for(const word of corpus.words){const v={bits:word};expect(validate({x:v,y:v,zoom:v})).toBe(true);}});
test("Generation native UTF8 domain excludes lossy owned string and dictionary key states",()=>{const source=proceduralSnapshotFixture(corpus),bad=String.fromCharCode(0xd800);expect(Buffer.from(bad).toString()).not.toBe(bad);expect(()=>parseGeneration2dArtifact({...source,hostSnapshot:{...source.hostSnapshot,schema:bad}})).toThrow();expect(()=>parseGeneration2dArtifact({...source,generation:{generations:[{id:"",name:"",values:{[bad]:{kind:"null"}}}]}})).toThrow();});
test("Generation canonical expanded native sets cannot represent duplicate or noncanonical occurrence arrays",()=>{const source=proceduralSnapshotFixture(corpus);expect(new Set(["a","a"]).size).toBe(1);for(const expanded of[["a","a"],["z","a"]])expect(()=>parseGeneration2dArtifact({...source,hostSnapshot:{...source.hostSnapshot,widgets:[{kind:"outputPreview",id:"",preview:{},expanded}]}})).toThrow();});
test("Generation authored schema admission precedes any borrowed snapshot field access",async()=>{const s=proceduralSnapshotFixture(corpus);let touched=false;const guarded={get hostSnapshot():typeof s.hostSnapshot{touched=true;throw Error("unadmitted borrowed domain access");},generation:s.generation};await expect(generation2dSnapshotToSqliteDatabase(guarded,{maxSchemaBytes:1})).rejects.toThrow("schema limit");expect(touched).toBe(false);});
test("Generation actual move-nodes consumer returns canonical bit-backed layout",()=>{const delta=moveNodeDiff({ids:["x"],dx:binary64(2),dy:binary64(3)} as never,{x:{x:binary64(1),y:binary64(4)}} as never),s=proceduralSnapshotFixture(corpus);const layout=Object.fromEntries(delta.layout.set),back=parseGeneration2dArtifact({...s,hostSnapshot:{...s.hostSnapshot,layout}});expect(binary64Value(back.hostSnapshot.layout.x!.x)).toBe(3);expect(binary64Value(back.hostSnapshot.layout.x!.y)).toBe(7);});
test("Generation actual authored mutation positions retain the complete native64 width",()=>{for(const word of corpus.usizeWords){const index:CreateWidget["index"]=BigInt(word),v={index,widget:{kind:"inputNote" as const,id:"",text:""}},change=create3dWidgetDiff(v);const buffer=new ArrayBuffer(8),oracle=new DataView(buffer);oracle.setBigUint64(0,BigInt(word));expect(oracle.getBigUint64(0).toString()).toBe(word);expect(change.widgets.set[0]![0]).toBe(BigInt(word));}});
test("Generation actual committed numeric JSON gesture witnesses bind to canonical owned fields",()=>{expect(generation2dGestureLeafTwinSelfTests()).toBeGreaterThan(0);});
test("Generation independently consistent SQLite entity renumbering preserves logical snapshot",async()=>{const source=proceduralSnapshotFixture(corpus),db=Database.deserialize(await exportSqliteDatabase(await generation2dSnapshotToSqliteDatabase(source)));try{db.exec("PRAGMA foreign_keys=OFF");const tables=db.query("SELECT name FROM sqlite_schema WHERE type='table' ORDER BY name").all() as {name:string}[];for(const {name}of tables){const links=db.query(`PRAGMA foreign_key_list(${name})`).all() as {from:string}[];const fields=["id=id+1000",...links.filter(v=>v.from!=="id").map(v=>`${v.from}=${v.from}+1000`)];db.exec(`UPDATE ${name} SET ${fields.join(',')}`);}expect(db.query("PRAGMA integrity_check").get()).toEqual({integrity_check:"ok"});expect(db.query("PRAGMA foreign_key_check").all()).toEqual([]);expect(await generation2dSnapshotFromSqliteDatabase(await importSqliteDatabase(db.serialize()))).toEqual(source);}finally{db.close();}});
for(const hex of corpus.words)test(`Generation independent SQLite query and reserialization preserves IEEE ${hex}`,async()=>{const source=proceduralSnapshotFixture(corpus),bits=BigInt(`0x${hex}`),word={bits},snapshot={...source,hostSnapshot:{...source.hostSnapshot,camera:{x:word,y:word,zoom:word},widgets:[],synapses:[],layout:{}},generation:{generations:[]}},db=Database.deserialize(await exportSqliteDatabase(await generation2dSnapshotToSqliteDatabase(snapshot)));try{const query=db.query("SELECT camera_x_bits,camera_x_class,camera_x FROM generation_host") as unknown as {safeIntegers(enabled:boolean):unknown;get():{camera_x_bits:bigint;camera_x_class:string;camera_x:number|null}|null};query.safeIntegers(true);const row=query.get()!,buffer=new ArrayBuffer(8),oracle=new DataView(buffer);oracle.setBigUint64(0,bits);expect(row.camera_x_bits).toBe(oracle.getBigInt64(0));if((bits&0x7ff0000000000000n)===0x7ff0000000000000n&&(bits&0xfffffffffffffn)!==0n){expect(row.camera_x_class).toBe("nan");expect(row.camera_x).toBeNull();}expect(db.query("PRAGMA integrity_check").get()).toEqual({integrity_check:"ok"});expect((await generation2dSnapshotFromSqliteDatabase(await importSqliteDatabase(db.serialize()))).hostSnapshot.camera.x.bits).toBe(bits);}finally{db.close();}});
test("procedural2d explicit retained empty model and independently owned SQL",async()=>{const s={hostSnapshot:{schema:"owned empty 日本",camera:{x:{bits:0x8000000000000000n},y:{bits:0x7ff0000000000000n},zoom:{bits:0x7ff0000000000001n}},widgets:[],synapses:[],layout:{}},generation:{generations:[],selectedGenerationId:"",previewText:""}};const d=await generation2dSnapshotToSqliteDatabase(s);expect(d.tables.length).toBe(36);const native=Database.deserialize(await exportSqliteDatabase(d));expect(native.query("PRAGMA integrity_check").get()).toEqual({integrity_check:"ok"});expect(native.query("PRAGMA foreign_key_check").all()).toEqual([]);native.query("UPDATE generation_document SET preview_text='independent exact 日本'").run();const edited=await generation2dSnapshotFromSqliteDatabase(await importSqliteDatabase(native.serialize()));expect(edited.generation.previewText).toBe("independent exact 日本");expect(edited.hostSnapshot.camera.zoom.bits).toBe(0x7ff0000000000001n);const contract=new Database(":memory:");contract.exec(GENERATION2D_SQLITE_SCHEMA);expect(contract.query("SELECT count(*) AS n FROM sqlite_schema WHERE type='table'").get()).toEqual({n:36});native.close();contract.close();});

test("all procedural owned variants retain exact primitives through an independent SQLite producer",async()=>{const s=proceduralSnapshotFixture(corpus);expect(parseGeneration2dArtifact(s)).toBe(s);const d=await generation2dSnapshotToSqliteDatabase(s),oracle=new Database(":memory:");oracle.exec("PRAGMA application_id=1397576526;PRAGMA user_version=1");oracle.exec(GENERATION2D_SQLITE_SCHEMA);for(const t of d.tables)for(const row of t.rows)oracle.query(`INSERT INTO ${t.name} VALUES(${row.values.map(()=>"?").join(",")})`).run(...row.values);try{expect(oracle.query("PRAGMA integrity_check").get()).toEqual({integrity_check:"ok"});expect(oracle.query("PRAGMA foreign_key_check").all()).toEqual([]);expect(oracle.query("SELECT count(*) AS n FROM generation_widget").get()).toEqual({n:corpus.expected.widgets});expect(oracle.query("SELECT unsigned_value FROM generation_value WHERE kind='unsigned' AND unsigned_value='18446744073709551615' LIMIT 1").get()).toEqual({unsigned_value:"18446744073709551615"});expect(oracle.query("SELECT hex(bytes_value) AS hex FROM generation_value WHERE kind='bytes' AND hex(bytes_value)='0001FF7F' LIMIT 1").get()).toEqual({hex:"0001FF7F"});const back=await generation2dSnapshotFromSqliteDatabase(await importSqliteDatabase(oracle.serialize()));expect(back).toEqual(s);expect(await generation2dSnapshotToSqliteDatabase(back)).toEqual(d);oracle.exec("UPDATE generation_note_widget SET text='edited independent Unicode 日本'");const edited=await generation2dSnapshotFromSqliteDatabase(await importSqliteDatabase(oracle.serialize()));expect(edited.hostSnapshot.widgets[2]).toMatchObject({kind:"inputNote",text:"edited independent Unicode 日本"});}finally{oracle.close();}});

test("procedural reconstruction rejects malformed ownership, shape, order and IEEE companions",async()=>{const source=await generation2dSnapshotToSqliteDatabase(proceduralSnapshotFixture(corpus));const changes=["UPDATE generation_widget SET ordinal=99 WHERE id=1","UPDATE generation_neuron_widget SET parameters_id=999999","DELETE FROM generation_note_widget","UPDATE generation_neural_entry SET value_id=(SELECT value_id FROM generation_neural_entry ORDER BY id LIMIT 1) WHERE id=2","UPDATE generation_host SET camera_x_class='positiveInfinity'","UPDATE generation_gui_preview SET source_channel=NULL WHERE source_neuron IS NOT NULL","UPDATE generation_value SET string_value='wrong inactive scalar' WHERE kind='boolean'","UPDATE generation_array_element SET value_id=array_id WHERE ordinal=0"];for(const change of changes){const native=Database.deserialize(await exportSqliteDatabase(source));try{native.exec(change);await expect(generation2dSnapshotFromSqliteDatabase(await importSqliteDatabase(native.serialize()))).rejects.toThrow();}finally{native.close();}}await expect(generation2dSnapshotToSqliteDatabase(proceduralSnapshotFixture(corpus),{maxValueBytes:16})).rejects.toThrow("value limit");const controller=new AbortController();await expect(generation2dSnapshotToSqliteDatabase(proceduralSnapshotFixture(corpus),{signal:controller.signal,onProgress:p=>{if(p.completed>0)controller.abort();}})).rejects.toHaveProperty("kind","canceled");const cancelled=new AbortController();await expect(generation2dSnapshotFromSqliteDatabase(source,{signal:cancelled.signal,onProgress:p=>{if(p.phase==="reconstructSnapshot")cancelled.abort();}})).rejects.toHaveProperty("kind","canceled");});

test("deep intrinsic answers remain iterative and byte ownership stays detached",async()=>{const s=proceduralSnapshotFixture(corpus);let v:GenerationValue={kind:"bytes",value:Uint8Array.of(0,255)};for(let i=0;i<1024;i++)v={kind:"array",values:[v]};const snapshot={...s,generation:{generations:[{id:"deep",name:"",values:{deep:v}}]}};const d=await generation2dSnapshotToSqliteDatabase(snapshot),back=await generation2dSnapshotFromSqliteDatabase(d);let value=back.generation.generations[0]!.values.deep!;for(let i=0;i<1024;i++){expect(value.kind).toBe("array");if(value.kind!=="array")throw Error("deep answer differs");value=value.values[0]!;}expect(value).toEqual({kind:"bytes",value:Uint8Array.of(0,255)});if(value.kind!=="bytes")throw Error("deep answer primitive differs");value.value.fill(42);const again=await generation2dSnapshotFromSqliteDatabase(d);let fresh=again.generation.generations[0]!.values.deep!;while(fresh.kind==="array")fresh=fresh.values[0]!;expect(fresh).toEqual({kind:"bytes",value:Uint8Array.of(0,255)});});

test("procedural owned field shapes reject unsupported inactive or extraneous state",()=>{const s=proceduralSnapshotFixture(corpus);const cases=[{...s,extra:true},{...s,hostSnapshot:{...s.hostSnapshot,camera:{...s.hostSnapshot.camera,extra:true}}},{...s,hostSnapshot:{...s.hostSnapshot,widgets:[{kind:"inputNote",id:"n",text:"",value:true}]}},{...s,hostSnapshot:{...s.hostSnapshot,widgets:[{kind:"neuron",id:"n",neuronKind:"",params:{bad:{kind:"null",value:true}},inputPorts:[],outputPorts:[],preview:false}]}},{...s,generation:{generations:[{id:"",name:"",values:{bad:{kind:"null",value:1}}}]}}];for(const value of cases)expect(()=>parseGeneration2dArtifact(value)).toThrow();});

test("projection admits the closed owned shape under bounded cancellation",async()=>{const s=proceduralSnapshotFixture(corpus);await expect(generation2dSnapshotToSqliteDatabase({...s,extra:true} as typeof s)).rejects.toThrow("unsupported procedural owned field");const large={...s,generation:{generations:[{id:"",name:"",values:Object.fromEntries(Array.from({length:1024},(_,i)=>[String(i),{kind:"null" as const}]))}]}};const controller=new AbortController();let checkpoints=0;await expect(generation2dSnapshotToSqliteDatabase(large,{signal:controller.signal,onProgress:p=>{if(p.phase==="projectSnapshot"&&p.completed===256){checkpoints++;controller.abort();}}})).rejects.toHaveProperty("kind","canceled");expect(checkpoints).toBe(1);});


import semanticCells from "../../../../../../../../../../\u{1fac0}\uFE0Fcore/\u{1f9ec}\uFE0Fgeneration/\u{1fab6}\uFE0Fsqlite/\u{1f9eb}\uFE0Ffixtures/\u{1f4cf}\uFE0Fsemantic-cells.json";
test("complete SQL semantic cells match both independently owned native families",async()=>{
 for(const c of semanticCells.cases){
  const s=proceduralSnapshotFixture(corpus);if(c.word!==null)s.hostSnapshot.camera.x={bits:BigInt("0x"+c.word)};
  const d=await generation2dSnapshotToSqliteDatabase(s),oracle=Database.deserialize(await exportSqliteDatabase(d));
  try{expect(oracle.query("PRAGMA integrity_check").get()).toEqual({integrity_check:"ok"});expect(oracle.query("PRAGMA foreign_key_check").all()).toEqual([]);expect(d.tables.map(t=>t.name)).toEqual(semanticCells.tables);let bytes=0,rows=0;for(const t of d.tables){const actual=oracle.query<Record<string,null|string|number|bigint|Uint8Array>,[]>('SELECT * FROM "'+t.name+'"').all();rows+=actual.length;for(const row of actual)for(const value of Object.values(row))bytes+=value===null?0:typeof value==="string"?Buffer.byteLength(value,"utf8"):value instanceof Uint8Array?value.length:8;}expect(rows).toBe(semanticCells.rows);expect(bytes).toBe(c.bytes);
   expect(await generation2dSnapshotToSqliteDatabase(s,{maxValueBytes:c.bytes})).toEqual(d);
   expect(await generation2dSnapshotFromSqliteDatabase(d,{maxValueBytes:c.bytes})).toEqual(s);
   await expect(generation2dSnapshotToSqliteDatabase(s,{maxValueBytes:c.bytes-1})).rejects.toThrow();
   await expect(generation2dSnapshotFromSqliteDatabase(d,{maxValueBytes:c.bytes-1})).rejects.toThrow();
  }finally{oracle.close()}
 }
});

