    return 0;
  }
  console.error(`usage: 📜️script.ts <generate|manifests|list-recipes|document|document-manifests> [--only <recipe-id>] [--out <dir>]`);
  return 2;
}

if (import.meta.main) process.exit(await main(process.argv.slice(2)));
//#endregion 🚪️Entry

