  if (APPLICATION_RECIPES.has(id)) return APPLICATION_FIXTURES_DIR;
  if (COMMENT_RECIPES.has(id)) return COMMENT_FIXTURES_DIR;
  if (GRAPHIC_CONTROL_RECIPES.has(id)) return GRAPHIC_CONTROL_FIXTURES_DIR;
