/** 📋️ Builds the manifest entry from files ALREADY on disk — never rebuilds, never rewrites what
 *  it just hashed (playbook step 5.4). `build` (below) is the only command that writes bytes. */
function readerManifestEntry(recipe: ReaderRecipe, outDir: string): Record<string, unknown> {
  const directory = FIXTURE_DIRECTORY_NAMES[recipe.id]!;
  const dir = join(outDir, directory);
  const files = [readerFileEntry("expected-before-gif", dir, BEFORE_FILE, directory), readerFileEntry("expected-after-gif", dir, AFTER_FILE, directory)];
  return {
    id: recipe.id,
    class: "third-party-generated",
    target: { artifact: "s.stdio.gif", standard: "89a", subset: "any" },
    mutation: recipe.mutation,
    outcome: recipe.outcome,
    units: { length: "unitless", angle: "degree" },
    files,
    generator: {
      oracle: READER_ORACLE_ID,
      packageVersion: READER_ENGINE_VERSION,
      engineFamily: "gif",
      engineVersion: READER_ENGINE_VERSION,
      command: `bun ✏️s/🔌️plugins/🗄️stdio/🗿️artifacts/🎞️gif/🏅️standards/9️⃣89a/🪆️subsets/🧱️base/🏭️generator/📜️script.ts build --only ${recipe.id}`,
      platform: platformId(),
    },
    provenance: { source: "generated", license: "MIT OR Apache-2.0 (gif)", attribution: "Generated with gif (MIT OR Apache-2.0) via the standalone reader binary in 🧫️fixtures/📖️reader/🦀️.rs", security: "scanned-clean", privacy: "no-personal-data" },
