const FIXED_STAMP_HEADER: &str = "  0\nSECTION\n  2\nHEADER\n  9\n$ACADVER\n  1\nAC1009\n  9\n$TDCREATE\n 40\n2461281.0\n  9\n$TDUPDATE\n 40\n2461281.0\n  0\nENDSEC\n  0\nEOF\n";

