        on_layer("DIMS", EntityType::Solid(Solid { first_corner: Point::new(0.0, 0.0, 0.0), second_corner: Point::new(60.0, 0.0, 0.0), third_corner: Point::new(60.0, 40.0, 0.0), fourth_corner: Point::new(0.0, 40.0, 0.0), ..Default::default() })),
